<?php
require_once ROOT.'/src/short-links.php';requireAdmin();shortSchema(db());$title=shortT('title');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(($_POST['action']??'')==='toggle'){$q=db()->prepare('UPDATE short_links SET active=1-active WHERE code=?');$q->execute([(string)($_POST['code']??'')]);audit('short-link-toggle',(string)($_POST['code']??''));redirect('/KNISA/short-links/?lang='.urlencode(siteLanguage()));}
  $code=shortCreate(db(),shortTrackedTarget((string)($_POST['target']??''),$_POST),(string)($_POST['code']??''));audit('short-link-create',$code);redirect('/KNISA/short-links/?lang='.urlencode(siteLanguage()).'&created='.urlencode($code));
 }catch(DomainException $ex){$error=shortT($ex->getMessage());}catch(Throwable $ex){error_log('Short link save failed');$error=shortT('error');}
}
ob_start();?><h1><?=e($title)?></h1><p><?=e(shortT('hint'))?></p>
<?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif?>
<?php if(isset($_GET['created'])&&preg_match('/^[a-zA-Z0-9_-]{1,24}$/D',(string)$_GET['created'])):?><p class="notice" role="status"><?=e(shortT('ready'))?> <a dir="ltr" href="<?=e(APP_URL.'/s/'.$_GET['created'])?>"><?=e(APP_URL.'/s/'.$_GET['created'])?></a></p><?php endif?>
<form method="post" class="form-panel admin-form"><?=csrf()?><label class="field"><?=e(shortT('target'))?><input name="target" type="text" dir="ltr" required maxlength="8000" value="<?=e($_POST['target']??'')?>"></label><label class="field"><?=e(shortT('alias'))?><input name="code" dir="ltr" pattern="[a-zA-Z0-9_-]{1,24}" maxlength="24" value="<?=e($_POST['code']??'')?>"></label><details><summary><?=e(shortT('tracking'))?></summary><?php foreach(['utm_source','utm_medium','utm_campaign','utm_content','utm_term','ref','param'] as $key):?><label class="field" dir="ltr"><?=e($key)?><input name="<?=e($key)?>" maxlength="250" value="<?=e($_POST[$key]??'')?>"></label><?php endforeach?></details><button class="button"><?=e(shortT('create'))?></button></form><p><?=e(shortT('measurement_note'))?></p>
<div class="table-scroll"><table class="admin-table"><thead><tr><?php foreach(['link','target','clicks','status'] as $key):?><th><?=e(shortT($key))?></th><?php endforeach?></tr></thead><tbody><?php foreach(query('SELECT * FROM short_links ORDER BY created DESC,rowid DESC LIMIT 300') as $row):$url=APP_URL.'/s/'.$row['code'];?><tr><td><a dir="ltr" href="<?=e($url)?>"><?=e($url)?></a><button type="button" data-short-copy="<?=e($url)?>" data-done="<?=e(shortT('copied'))?>"><?=e(shortT('copy'))?></button></td><td><details><summary><?=e(shortT('target'))?></summary><textarea readonly dir="ltr" aria-label="<?=e(shortT('target'))?>"><?=e($row['target'])?></textarea></details><details><summary><?=e(shortT('tracking'))?></summary><?php parse_str(parse_url($row['target'],PHP_URL_QUERY)??'', $tracking);foreach(['utm_source','utm_medium','utm_campaign','utm_content','utm_term','ref','param'] as $key):if(!isset($tracking[$key])||!is_string($tracking[$key]))continue;?><p dir="ltr"><strong><?=e($key)?></strong>: <?=e($tracking[$key])?></p><?php endforeach?></details></td><td><?=(int)$row['clicks']?><details><summary><?=e(shortT('sources'))?></summary><?php $q=query('SELECT referrer,count(*) AS n,max(created) AS last FROM short_link_visits WHERE code=? GROUP BY referrer ORDER BY n DESC LIMIT 100',[$row['code']]);foreach($q as $visit):?><p><bdi><?=e($visit['referrer']?:shortT('unknown'))?></bdi> · <?=(int)$visit['n']?> · <?=e(gmdate('Y-m-d H:i',(int)$visit['last']))?> UTC</p><?php endforeach?></details></td><td><?=e(shortT($row['active']?'active':'disabled'))?><form method="post"><?=csrf()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="code" value="<?=e($row['code'])?>"><button><?=e(shortT($row['active']?'disable':'enable'))?></button></form></td></tr><?php endforeach?></tbody></table></div><script src="/assets/short-links.js" defer></script><?php $content=ob_get_clean();require ROOT.'/views/admin-shell.php';
